#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testCapitalize();

void testCapitalize()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    // Test 1: Basic lowercase string
    assertTrue(isEqual(exchange.capitalize(std::string("hello")), std::string("Hello")));
    // Test 2: Preserve rest of string (camelCase)
    assertTrue(isEqual(exchange.capitalize(std::string("fooBar")), std::string("FooBar")));
    // Test 3: Preserve rest of string (mixed case)
    assertTrue(isEqual(exchange.capitalize(std::string("helloWorld")), std::string("HelloWorld")));
    // Test 4: Already capitalized
    assertTrue(isEqual(exchange.capitalize(std::string("Hello")), std::string("Hello")));
    // Test 5: All uppercase (should preserve rest)
    assertTrue(isEqual(exchange.capitalize(std::string("hELLO")), std::string("HELLO")));
    // Test 6: Single character lowercase
    assertTrue(isEqual(exchange.capitalize(std::string("a")), std::string("A")));
    // Test 7: Single character uppercase
    assertTrue(isEqual(exchange.capitalize(std::string("A")), std::string("A")));
    // Test 8: Empty string
    assertTrue(isEqual(exchange.capitalize(std::string("")), std::string("")));
    // Test 9: String starting with number
    assertTrue(isEqual(exchange.capitalize(std::string("123abc")), std::string("123abc")));
    // Test 10: String with spaces
    assertTrue(isEqual(exchange.capitalize(std::string("hello world")), std::string("Hello world")));
    // Test 11: Underscore separated (snake_case)
    assertTrue(isEqual(exchange.capitalize(std::string("foo_bar_baz")), std::string("Foo_bar_baz")));
    // Test 12: All caps input (preserve rest)
    assertTrue(isEqual(exchange.capitalize(std::string("aBC")), std::string("ABC")));
}

